
const WORDS=[{"id": 0, "w": "屡次", "p": "lǚcì", "t": "副词", "m": "nhiều lần, hết lần này đến lần khác", "coll": "屡次尝试、屡次失败", "s": "虽然屡次失败，她仍然没有放弃改进设计。"}, {"id": 1, "w": "依据", "p": "yījù", "t": "介词／动词／名词", "m": "căn cứ vào, dựa vào; căn cứ, cơ sở", "coll": "依据事实、法律依据", "s": "讨论问题时，我们应该依据事实，认真分析。"}, {"id": 2, "w": "罐", "p": "guàn", "t": "名词／量词", "m": "hũ, lọ, lon; đơn vị đếm lon, hũ", "coll": "一罐饮料、储物罐", "s": "她打开一罐饮料，递给刚到家的朋友。"}, {"id": 3, "w": "数额", "p": "shù’é", "t": "名词", "m": "số lượng, số tiền (được tính cụ thể)", "coll": "具体数额、数额较大", "s": "提交申请之前，请核对表格中填写的具体数额。"}, {"id": 4, "w": "永恒", "p": "yǒnghéng", "t": "形容词", "m": "vĩnh viễn, bất diệt, đời đời bền vững", "coll": "永恒的主题、永恒的价值", "s": "人与自然的关系是文学作品中一个永恒的主题。"}, {"id": 5, "w": "遵循", "p": "zūnxún", "t": "动词", "m": "tuân theo, theo", "coll": "遵循原则、遵循规律", "s": "设计产品时，应该遵循方便使用的原则。"}, {"id": 6, "w": "不屑", "p": "bùxiè", "t": "动词", "m": "coi là không đáng; không thèm", "coll": "不屑争辩、不屑一提", "s": "面对毫无根据的指责，他不屑争辩，只用事实作出回应。"}, {"id": 7, "w": "孕育", "p": "yùnyù", "t": "动词", "m": "thai nghén, nuôi dưỡng, ươm mầm, làm nảy sinh", "coll": "孕育希望、孕育新思想", "s": "不同领域的交流常常能够孕育出新的想法。"}, {"id": 8, "w": "博览会", "p": "bólǎnhuì", "t": "名词", "m": "hội chợ, cuộc triển lãm", "coll": "国际博览会、参加博览会", "s": "这家企业在国际博览会上展示了最新的产品。"}, {"id": 9, "w": "耐用", "p": "nàiyòng", "t": "形容词", "m": "bền, lâu bền", "coll": "结实耐用、耐用的材料", "s": "顾客更愿意选择那些设计简单、结实耐用的家具。"}, {"id": 10, "w": "魔术", "p": "móshù", "t": "名词", "m": "ảo thuật", "coll": "表演魔术、魔术表演", "s": "活动现场，一位年轻演员为孩子们表演了魔术。"}, {"id": 11, "w": "扣", "p": "kòu", "t": "动词", "m": "trừ đi, khấu trừ", "coll": "扣除费用、扣工资", "s": "结算时，工作人员先扣去了已经预付的费用。"}, {"id": 12, "w": "季度", "p": "jìdù", "t": "名词", "m": "quý, ba tháng", "coll": "第一季度、季度报告", "s": "公司计划在第一季度完成新产品的测试。"}, {"id": 13, "w": "本钱", "p": "běnqián", "t": "名词", "m": "tiền vốn", "coll": "投入本钱、积累本钱", "s": "开店之前，他通过工作慢慢积累了最初的本钱。"}, {"id": 14, "w": "通货膨胀", "p": "tōnghuò péngzhàng", "t": "名词", "m": "lạm phát", "coll": "通货膨胀率、通货膨胀现象", "s": "这本经济学教材解释了通货膨胀与物价上涨之间的关系。"}, {"id": 15, "w": "平庸", "p": "píngyōng", "t": "形容词", "m": "xoàng, tầm thường, bình thường", "coll": "表现平庸、不甘平庸", "s": "他不甘平庸，总想通过学习提高自己的能力。"}, {"id": 16, "w": "捏", "p": "niē", "t": "动词", "m": "bóp, nặn, véo; giữ bằng các đầu ngón tay", "coll": "捏面人、捏住纸角", "s": "小女孩捏着一小块面团，认真地做着小动物。"}, {"id": 17, "w": "环节", "p": "huánjié", "t": "名词", "m": "khâu, mắc xích", "coll": "关键环节、生产环节", "s": "为了提高效率，团队逐一检查了每个生产环节。"}, {"id": 18, "w": "兴旺", "p": "xīngwàng", "t": "形容词", "m": "thịnh vượng, phát đạt, hưng thịnh", "coll": "生意兴旺、繁荣兴旺", "s": "这家老店服务周到，多年来一直生意兴旺。"}, {"id": 19, "w": "垄断", "p": "lǒngduàn", "t": "动词", "m": "lũng đoạn, giữ độc quyền", "coll": "垄断市场、打破垄断", "s": "这篇文章分析了少数企业垄断市场所带来的问题。"}, {"id": 20, "w": "扩充", "p": "kuòchōng", "t": "动词", "m": "mở rộng, tăng thêm", "coll": "扩充队伍、扩充词汇量", "s": "随着业务增加，公司开始扩充服务团队。"}, {"id": 21, "w": "掏", "p": "tāo", "t": "动词", "m": "lấy ra, rút ra, móc", "coll": "掏出钱包、掏口袋", "s": "他从口袋里掏出一张纸条，递给了身边的同事。"}, {"id": 22, "w": "布局", "p": "bùjú", "t": "动词／名词", "m": "bố trí, sắp xếp; bố cục", "coll": "合理布局、整体布局", "s": "重新装修时，他们调整了店内的整体布局。"}, {"id": 23, "w": "拟定", "p": "nǐdìng", "t": "动词", "m": "định ra, vạch ra", "coll": "拟定计划、拟定方案", "s": "正式讨论之前，小组已经拟定了一份初步方案。"}, {"id": 24, "w": "策略", "p": "cèlüè", "t": "名词", "m": "sách lược, chiến lược", "coll": "营销策略、调整策略", "s": "了解顾客需求以后，公司及时调整了营销策略。"}, {"id": 25, "w": "咀嚼", "p": "jǔjué", "t": "动词", "m": "nhai; nghiền ngẫm", "coll": "慢慢咀嚼、反复咀嚼", "s": "他一边慢慢咀嚼着面包，一边听朋友讲旅途中的故事。"}, {"id": 26, "w": "可口", "p": "kěkǒu", "t": "形容词", "m": "ngon miệng, hợp khẩu vị", "coll": "美味可口、可口的饭菜", "s": "奶奶准备了一桌可口的饭菜，欢迎远道而来的客人。"}, {"id": 27, "w": "物美价廉", "p": "wùměi jiàlián", "t": "成语", "m": "hàng tốt giá rẻ", "coll": "物美价廉的商品、物美价廉", "s": "这家商店以物美价廉的商品吸引了不少回头客。"}, {"id": 28, "w": "风味", "p": "fēngwèi", "t": "名词", "m": "mùi vị, hương vị", "coll": "地方风味、独特风味", "s": "这道菜保留了家乡独特的风味。"}, {"id": 29, "w": "吹捧", "p": "chuīpěng", "t": "动词", "m": "tâng bốc, nịnh bợ", "coll": "过分吹捧、相互吹捧", "s": "评价作品时，应该实事求是，不要一味吹捧。"}, {"id": 30, "w": "品尝", "p": "pǐncháng", "t": "动词", "m": "nếm, thử, thưởng thức", "coll": "品尝美食、免费品尝", "s": "游客们在市场里品尝了几种当地小吃。"}, {"id": 31, "w": "踊跃", "p": "yǒngyuè", "t": "形容词", "m": "nô nức, tấp nập, háo hức", "coll": "踊跃报名、踊跃发言", "s": "得知有交流机会，同学们踊跃报名。"}, {"id": 32, "w": "井", "p": "jǐng", "t": "名词", "m": "giếng (nước, dầu...)", "coll": "一口井、井水", "s": "村口那口井曾经为居民提供了日常用水。"}, {"id": 33, "w": "财务", "p": "cáiwù", "t": "名词", "m": "tài chính", "coll": "财务管理、财务报告", "s": "这份财务报告清楚地列出了各项支出。"}, {"id": 34, "w": "局部", "p": "júbù", "t": "名词", "m": "bộ phận, phần", "coll": "局部地区、局部调整", "s": "设计方案只作了局部调整，整体结构没有改变。"}, {"id": 35, "w": "关照", "p": "guānzhào", "t": "动词", "m": "quan tâm, chăm sóc", "coll": "多加关照、互相关照", "s": "刚到这里时，她得到了邻居们的热心关照。"}, {"id": 36, "w": "观光", "p": "guānguāng", "t": "动词", "m": "tham quan", "coll": "观光旅游、到处观光", "s": "会议结束后，他们利用半天时间到城里观光。"}, {"id": 37, "w": "就近", "p": "jiùjìn", "t": "副词", "m": "ở gần, chọn nơi gần cho thuận tiện", "coll": "就近选择、就近安排", "s": "为了节省交通时间，大家决定就近选择一家餐馆。"}, {"id": 38, "w": "肖像", "p": "xiàoxiàng", "t": "名词", "m": "chân dung, ảnh", "coll": "人物肖像、肖像画", "s": "这位画家擅长通过细节表现人物肖像中的情感。"}, {"id": 39, "w": "纺织", "p": "fǎngzhī", "t": "动词", "m": "dệt", "coll": "纺织技术、纺织行业", "s": "博物馆用实物展示了传统纺织技术的发展过程。"}, {"id": 40, "w": "留念", "p": "liúniàn", "t": "动词", "m": "giữ làm lưu niệm", "coll": "合影留念、签名留念", "s": "活动结束时，大家站在展厅门口合影留念。"}, {"id": 41, "w": "对照", "p": "duìzhào", "t": "动词", "m": "so sánh, đối chiếu", "coll": "对照原文、逐项对照", "s": "修改译文时，她认真对照原文，检查是否遗漏了信息。"}, {"id": 42, "w": "齐心协力", "p": "qíxīn xiélì", "t": "成语", "m": "đồng tâm hiệp lực, đồng lòng góp sức", "coll": "齐心协力、齐心协力完成", "s": "大家齐心协力，展览终于按时布置完成。"}, {"id": 43, "w": "专长", "p": "zhuāncháng", "t": "名词", "m": "sở trường", "coll": "发挥专长、个人专长", "s": "负责人根据每个人的专长，合理分配了任务。"}, {"id": 44, "w": "资本", "p": "zīběn", "t": "名词", "m": "tư bản, vốn", "coll": "投入资本、资本积累", "s": "这本书介绍了企业发展中资本积累的作用。"}, {"id": 45, "w": "以往", "p": "yǐwǎng", "t": "名词", "m": "ngày xưa, trước kia", "coll": "与以往相比、以往的经验", "s": "与以往相比，这次活动增加了更多互动环节。"}, {"id": 46, "w": "淡季", "p": "dànjì", "t": "名词", "m": "mùa ế hàng, mùa ít khách, trái mùa", "coll": "旅游淡季、销售淡季", "s": "到了旅游淡季，这座小城又恢复了往日的宁静。"}, {"id": 47, "w": "制服", "p": "zhìfú", "t": "名词", "m": "đồ đồng phục", "coll": "穿制服、统一制服", "s": "展览开始之前，工作人员都换上了统一的制服。"}, {"id": 48, "w": "规格", "p": "guīgé", "t": "名词", "m": "quy cách, tiêu chuẩn", "coll": "产品规格、不同规格", "s": "购买零件之前，请先确认需要的规格。"}, {"id": 49, "w": "递增", "p": "dìzēng", "t": "动词", "m": "tăng dần", "coll": "逐年递增、数量递增", "s": "随着服务改善，这家店的回头客数量逐年递增。"}, {"id": 50, "w": "周期", "p": "zhōu qī", "t": "名词", "m": "chu kỳ", "coll": "生产周期、学习周期", "s": "调整工序以后，产品的生产周期明显缩短了。"}, {"id": 51, "w": "赌博", "p": "dǔbó", "t": "动词", "m": "đánh bạc, cờ bạc", "coll": "沉迷赌博、远离赌博", "s": "故事中的主人公因为沉迷赌博，失去了家人的信任。"}, {"id": 52, "w": "空想", "p": "kōngxiǎng", "t": "动词／名词", "m": "mơ tưởng viển vông; ý tưởng xa rời thực tế", "coll": "不切实际的空想、停留在空想", "s": "如果不付诸行动，再好的计划也只能停留在空想中。"}];
