'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk6-bai38-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/53 个词语。学完5组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),53)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共53个词语，点击 ↗ 学习该词语',totalLearned()+'/53 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、13个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===52;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<52){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:12};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课53个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课53个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [5, 20, 23], "5": [2, 10, 33], "8": [5, 20, 23], "11": [2, 10, 33], "14": [5, 20, 23], "17": [5, 20, 23], "20": [2, 10, 33], "23": [2, 10, 33], "26": [2, 10, 33], "29": [2, 10, 33], "32": [5, 20, 23], "35": [2, 10, 33], "38": [5, 20, 23], "41": [2, 10, 33], "44": [5, 20, 23], "47": [5, 20, 23], "50": [5, 20, 23]};
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的53个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第38课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第38课学习进度','第38课 · 53个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 53</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第38课';$('ntc-bookmark').textContent=student?total+'/53 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第38课学习进度</div><div style="padding:0 10px">'+total+'/53 个已学词语'+meter(total,53)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
const AUDIO_INDEX={"屡次":"data:audio/mpeg;base64,","虽然屡次失败，她仍然没有放弃改进设计。":"data:audio/mpeg;base64,","依据":"data:audio/mpeg;base64,","讨论问题时，我们应该依据事实，认真分析。":"data:audio/mpeg;base64,","罐":"data:audio/mpeg;base64,","她打开一罐饮料，递给刚到家的朋友。":"data:audio/mpeg;base64,","数额":"data:audio/mpeg;base64,","提交申请之前，请核对表格中填写的具体数额。":"data:audio/mpeg;base64,","永恒":"data:audio/mpeg;base64,","人与自然的关系是文学作品中一个永恒的主题。":"data:audio/mpeg;base64,","遵循":"data:audio/mpeg;base64,","设计产品时，应该遵循方便使用的原则。":"data:audio/mpeg;base64,","不屑":"data:audio/mpeg;base64,","面对毫无根据的指责，他不屑争辩，只用事实作出回应。":"data:audio/mpeg;base64,","孕育":"data:audio/mpeg;base64,","不同领域的交流常常能够孕育出新的想法。":"data:audio/mpeg;base64,","博览会":"data:audio/mpeg;base64,","这家企业在国际博览会上展示了最新的产品。":"data:audio/mpeg;base64,","耐用":"data:audio/mpeg;base64,","顾客更愿意选择那些设计简单、结实耐用的家具。":"data:audio/mpeg;base64,","魔术":"data:audio/mpeg;base64,","活动现场，一位年轻演员为孩子们表演了魔术。":"data:audio/mpeg;base64,","扣":"data:audio/mpeg;base64,","结算时，工作人员先扣去了已经预付的费用。":"data:audio/mpeg;base64,","季度":"data:audio/mpeg;base64,","公司计划在第一季度完成新产品的测试。":"data:audio/mpeg;base64,","本钱":"data:audio/mpeg;base64,","开店之前，他通过工作慢慢积累了最初的本钱。":"data:audio/mpeg;base64,","通货膨胀":"data:audio/mpeg;base64,","这本经济学教材解释了通货膨胀与物价上涨之间的关系。":"data:audio/mpeg;base64,","平庸":"data:audio/mpeg;base64,","他不甘平庸，总想通过学习提高自己的能力。":"data:audio/mpeg;base64,","捏":"data:audio/mpeg;base64,","小女孩捏着一小块面团，认真地做着小动物。":"data:audio/mpeg;base64,","环节":"data:audio/mpeg;base64,","为了提高效率，团队逐一检查了每个生产环节。":"data:audio/mpeg;base64,","兴旺":"data:audio/mpeg;base64,","这家老店服务周到，多年来一直生意兴旺。":"data:audio/mpeg;base64,","垄断":"data:audio/mpeg;base64,","这篇文章分析了少数企业垄断市场所带来的问题。":"data:audio/mpeg;base64,","扩充":"data:audio/mpeg;base64,","随着业务增加，公司开始扩充服务团队。":"data:audio/mpeg;base64,","掏":"data:audio/mpeg;base64,","他从口袋里掏出一张纸条，递给了身边的同事。":"data:audio/mpeg;base64,","布局":"data:audio/mpeg;base64,","重新装修时，他们调整了店内的整体布局。":"data:audio/mpeg;base64,","拟定":"data:audio/mpeg;base64,","正式讨论之前，小组已经拟定了一份初步方案。":"data:audio/mpeg;base64,","策略":"data:audio/mpeg;base64,","了解顾客需求以后，公司及时调整了营销策略。":"data:audio/mpeg;base64,","咀嚼":"data:audio/mpeg;base64,","他一边慢慢咀嚼着面包，一边听朋友讲旅途中的故事。":"data:audio/mpeg;base64,","可口":"data:audio/mpeg;base64,","奶奶准备了一桌可口的饭菜，欢迎远道而来的客人。":"data:audio/mpeg;base64,","物美价廉":"data:audio/mpeg;base64,","这家商店以物美价廉的商品吸引了不少回头客。":"data:audio/mpeg;base64,","风味":"data:audio/mpeg;base64,","这道菜保留了家乡独特的风味。":"data:audio/mpeg;base64,","吹捧":"data:audio/mpeg;base64,","评价作品时，应该实事求是，不要一味吹捧。":"data:audio/mpeg;base64,","品尝":"data:audio/mpeg;base64,","游客们在市场里品尝了几种当地小吃。":"data:audio/mpeg;base64,","踊跃":"data:audio/mpeg;base64,","得知有交流机会，同学们踊跃报名。":"data:audio/mpeg;base64,","井":"data:audio/mpeg;base64,","村口那口井曾经为居民提供了日常用水。":"data:audio/mpeg;base64,","财务":"data:audio/mpeg;base64,","这份财务报告清楚地列出了各项支出。":"data:audio/mpeg;base64,","局部":"data:audio/mpeg;base64,","设计方案只作了局部调整，整体结构没有改变。":"data:audio/mpeg;base64,","关照":"data:audio/mpeg;base64,","刚到这里时，她得到了邻居们的热心关照。":"data:audio/mpeg;base64,","观光":"data:audio/mpeg;base64,","会议结束后，他们利用半天时间到城里观光。":"data:audio/mpeg;base64,","就近":"data:audio/mpeg;base64,","为了节省交通时间，大家决定就近选择一家餐馆。":"data:audio/mpeg;base64,","肖像":"data:audio/mpeg;base64,","这位画家擅长通过细节表现人物肖像中的情感。":"data:audio/mpeg;base64,","纺织":"data:audio/mpeg;base64,","博物馆用实物展示了传统纺织技术的发展过程。":"data:audio/mpeg;base64,","留念":"data:audio/mpeg;base64,","活动结束时，大家站在展厅门口合影留念。":"data:audio/mpeg;base64,","对照":"data:audio/mpeg;base64,","修改译文时，她认真对照原文，检查是否遗漏了信息。":"data:audio/mpeg;base64,","齐心协力":"data:audio/mpeg;base64,","大家齐心协力，展览终于按时布置完成。":"data:audio/mpeg;base64,","专长":"data:audio/mpeg;base64,","负责人根据每个人的专长，合理分配了任务。":"data:audio/mpeg;base64,","资本":"data:audio/mpeg;base64,","这本书介绍了企业发展中资本积累的作用。":"data:audio/mpeg;base64,","以往":"data:audio/mpeg;base64,","与以往相比，这次活动增加了更多互动环节。":"data:audio/mpeg;base64,","淡季":"data:audio/mpeg;base64,","到了旅游淡季，这座小城又恢复了往日的宁静。":"data:audio/mpeg;base64,","制服":"data:audio/mpeg;base64,","展览开始之前，工作人员都换上了统一的制服。":"data:audio/mpeg;base64,","规格":"data:audio/mpeg;base64,","购买零件之前，请先确认需要的规格。":"data:audio/mpeg;base64,","递增":"data:audio/mpeg;base64,","随着服务改善，这家店的回头客数量逐年递增。":"data:audio/mpeg;base64,","周期":"data:audio/mpeg;base64,","调整工序以后，产品的生产周期明显缩短了。":"data:audio/mpeg;base64,","赌博":"data:audio/mpeg;base64,","故事中的主人公因为沉迷赌博，失去了家人的信任。":"data:audio/mpeg;base64,","空想":"data:audio/mpeg;base64,","如果不付诸行动，再好的计划也只能停留在空想中。":"data:audio/mpeg;base64,"};
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai38-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai38_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai38-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=53)||!p.memory)throw Error();if(!confirm('恢复第38课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<53;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<53&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第38课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

